from pathlib import Path
import json,html
R=Path(__file__).resolve().parent.parent
S=R/'source'
I=json.loads((S/'icons.json').read_text())
def icon(n):return I.get(n,I['Check'])
def a(label,target,cls='textlink'):return f'<a class="{cls}" href="{target}.html">{label}</a>'
def btn(label,target,secondary=False):return a(label,target,'button secondary' if secondary else 'button')
def image(name,alt,cls=''):return f'<img src="../assets/{name}.png" alt="{alt}" class="{cls}" loading="eager">'
def field(label,value='',help='',error='',type='text',placeholder='',id=None):
 id=id or label.lower().replace(' ','-').replace('(','').replace(')','')
 return f'<div class="field"><label for="{id}">{label}</label><input id="{id}" type="{type}" value="{html.escape(value,quote=True)}" placeholder="{placeholder}" '+(f'aria-invalid="true" aria-describedby="{id}-error"' if error else f'aria-describedby="{id}-help"' if help else '')+f'>{f"<span id={id}-help class=help>{help}</span>" if help else ""}'+(f'<span class="error-text" id="{id}-error">{error}</span>' if error else '')+'</div>'
def notice(text,kind='info'):return f'<div class="notice {kind}">{icon("Info" if kind=="info" else "CircleHelp" if kind=="error" else "CheckCircle2")}<p>{text}</p></div>'
def facts(items):return '<dl class="facts">'+''.join(f'<div><dt>{k}</dt><dd>{v}</dd></div>' for k,v in items)+'</dl>'
def header():return f'''<div class="announcement">Make room for a little personal meaning.</div><header class="header"><div class="wrap header-inner"><div class="row gap8"><details class="menu"><summary class="iconbtn" aria-label="Open navigation">{icon('Menu')}</summary><nav class="panel stack">{a('Choose a base','03-collection')}{a('How it works','02-home-bottom')}{a('Personalization guide','05-product-specify')}{a('My account','12-profile')}</nav></details>{a('Made<span>Yours</span>','01-home-top','brand')}</div><nav class="nav" aria-label="Main">{a('Choose a base','03-collection','')}{a('How it works','02-home-bottom','')}{a('Examples','05-product-specify','')}{a('Production & care','06-product-review','')}</nav><div class="utilities">{a(icon('Search'),'03-collection','iconbtn search')}{a(icon('UserRound')+'<span class="account-label">Account</span>','12-profile','iconbtn account')}{a(icon('ShoppingBag')+'<span>2</span>','07-cart','iconbtn')}</div></div></header>'''
def footer():return f'''<footer class="footer"><div class="wrap"><div class="footer-grid"><div><div class="brand">MadeYours</div><p style="margin-top:16px">A considered base. A few meaningful words. An object that feels like yours.</p></div><div><h3>Make it yours</h3><nav>{a('Choose a base','03-collection','')}{a('Text & placement guide','05-product-specify','')}{a('How it works','02-home-bottom','')}</nav></div><div><h3>Here to help</h3><nav>{a('Production & returns','06-product-review','')}{a('Your orders','13-orders','')}{a('Your account','12-profile','')}</nav></div></div><div class="footer-base"><span>© 2026 MadeYours · Fictional visual study</span><span>Powered by LetBuyy · India / INR ₹</span></div></div></footer>'''
def crumb(last,product=False):return f'<div class="wrap breadcrumb">{a("Home","01-home-top","")}{icon("ChevronRight")}{a("Choose a base","03-collection","")}{icon("ChevronRight")}<span>{last}</span></div>'
def study():return '<div class="wrap demo-note">Design study · Fictional catalog and account · Proposed flows; no live cart, payment or account actions.</div>'
def steps(n):
 return '<ol class="stepper" aria-label="Personalization progress">'+''.join(f'<li class="{"active" if i==n else ""}"><span class="number">{i:02}</span>{t}</li>' for i,t in enumerate(['Choose','Specify','Review'],1))+'</ol>'
def stage(preview=False,last=False):return f'''<figure class="stage"><div class="stage-photo">{image('block','Blank walnut desk name block; front face shown for placement')}{'<span class="engraving" aria-hidden="true">Asha</span>' if preview else ''}</div><figcaption>{'Illustrative preview · Text placement and grain may vary. The written summary is authoritative.' if preview else 'Walnut base · 20 × 5 × 3 cm · Front face available for engraving.'}{' Showing last valid text “Asha”; your unvalidated edit is retained.' if last else ''}</figcaption></figure>'''
def context(label):return f'<div class="context-strip"><div class="wrap"><div class="row">{image("block","Walnut base")}<div><strong>Desk name block</strong><br><span class="muted">Walnut · ₹1,290 · {label}</span></div></div>{a("Back to selection","04-product-main","button secondary")}</div></div>'
def card(key):
 name,desc,limit,price=('Desk name block','Walnut · Front-face engraving','Up to 18 characters','₹1,290') if key=='block' else ('Everyday notebook','Ivory linen / Indigo spine · Cover print','Up to 12 characters','₹790')
 target='04-product-main' if key=='block' else 'notebook-reference'
 return f'<article class="product-card">{a(image(key,name,"product-photo"),target,"")}<div class="product-info"><span class="eyebrow">{desc}</span><div class="row between start"><h3>{a(name,target,"")}</h3><span class="price">{price}</span></div><p class="small">One name. One deliberate place.</p><div class="limits"><span>{limit}</span><span>Text included</span></div><div style="margin-top:20px">{btn("Choose this base "+icon("ArrowRight"),target,True)}</div></div></article>'
def cartline(name,num,edit=False):return f'''<article class="cart-line">{image('block','Walnut desk name block')}<div><div class="row between start"><h3>Desk name block</h3><span class="price">₹1,290</span></div><p class="small" style="margin-top:8px">Walnut · Front engraving · Quantity 1</p><p class="line-text">Exact text: <strong>“{name}”</strong></p><p class="small">Sans · Centered · Text included</p><div class="row between" style="margin-top:18px"><div class="qty" aria-label="Quantity for {name}"><button aria-label="Decrease quantity for {name}">{icon('Minus')}</button><span>1</span><button aria-label="Increase quantity for {name}">{icon('Plus')}</button></div><div class="row">{a('Edit text','05-product-specify')}{a('Remove','07-cart')}</div></div><span class="badge good" style="margin-top:16px">{icon('Check')} Validated configuration {num}</span></div></article>'''
def mini(name):return f'<div class="mini-line">{image("block","Walnut block")}<div><strong>Desk name block × 1</strong><p>Walnut · Exact text: <b>{name}</b><br>Sans · Centered · Front engraving</p></div><span class="price">₹1,290</span></div>'
def totals(final=True):return '<dl class="totals"><div><dt>Items (2)</dt><dd>₹2,580</dd></div><div><dt>Shipping</dt><dd>'+('₹80' if final else 'At checkout')+'</dd></div><div class="grand"><dt>'+('Total' if final else 'Subtotal')+'</dt><dd>'+('₹2,660' if final else '₹2,580')+'</dd></div></dl>'+( '<p class="small">Includes ₹405.76 tax in this illustrative quote.</p>' if final else '<p class="small">Shipping and final taxes are confirmed at checkout.</p>')
def summary(final=True,cta=''):
 return f'<aside class="summary"><div class="row between"><h2>Your configuration</h2><span class="badge outline">Mock quote</span></div>{mini("Asha")}{mini("Kabir")}{totals(final)}{cta}<hr class="divider"><p class="small">Each name is a separate configured item. The exact accepted text travels with its item.</p></aside>'
def checkout_header():return f'<header class="checkout-header"><div class="wrap row between">{a("MadeYours","07-cart","brand")}<div class="row small">{icon("LockKeyhole")} Shared LetBuyy checkout</div></div></header>'
def checkoutsteps(n):return '<ol class="stepper" aria-label="Checkout progress">'+''.join(f'<li class="{"active" if i==n else ""}"><span class="number">{i}</span>{x}</li>' for i,x in enumerate(['Address','Review & pay'],1))+'</ol>'
def checkoutfoot():return '<div class="checkout-footer"><span>Payments and orders handled by LetBuyy’s canonical checkout</span><span>Fictional quote · No payment is processed</span></div>'
def accountnav(active):
 return '<nav class="account-nav" aria-label="Account">'+''.join(a(icon(ic)+title,target,'active' if active==target else '') for title,target,ic in [('Overview','12-profile','UserRound'),('Orders','13-orders','Package'),('Addresses','15-addresses','MapPin'),('Sign out','10-sign-in','LogOut')])+'</nav>'
def account(content,active):return header()+f'<div class="wrap section account-layout">{accountnav(active)}<main class="account-main">{content}</main></div>'+study()+footer()
def address():return '<div class="address"><strong>Asha Mehta</strong>24 Example Lane<br>Sample Nagar<br>Bengaluru, Karnataka 560001<br>India</div>'
def identity(content):return f'''<div class="identity"><header class="identity-head"><a href="10-sign-in.html"><img class="identity-logo" src="../assets/letbuyy-logo.svg" alt="LetBuyy"></a><span>Continue to <strong>MadeYours</strong></span></header><main class="identity-body"><section class="identity-card"><div class="destination">{icon('ShoppingBag')} Your destination: MadeYours</div>{content}</section><p class="small" style="text-align:center;margin-top:24px">Canonical LetBuyy identity · Fictional form study</p></main><footer class="identity-foot"><span>Privacy</span><span>Terms</span><span>Help</span></footer></div>'''
scenes=[]
def save(id,title,desc,content,route,state):
 doc=f'<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>{title} · MadeYours design study</title><link rel="stylesheet" href="styles.css"><script defer src="presentation.js"></script></head><body data-scene="{id}">{content}</body></html>'
 (S/f'{id}.html').write_text(doc)
 scenes.append({'id':id,'title':title,'description':desc,'source':f'source/{id}.html','productionRoute':route,'state':state,'status':'visual_proposal_not_integrated'})
# 01 HOME TOP
save('01-home-top','A considered base. Your words.','Process-led opening, original product still life, choose CTA and visible three-stage journey.',header()+'''<main class="wrap section"><section class="hero"><div class="hero-copy"><span class="eyebrow">Small objects. Personal meaning.</span><h1>Good things.<br>Your words.</h1><p>Choose an everyday object. Add a name that matters. Review every detail before we make it yours.</p><div class="row">'''+btn('Choose your base '+icon('ArrowRight'),'03-collection')+a('See how it works','02-home-bottom')+'''</div><p class="small" style="margin-top:24px">Text personalization only · Clear limits on every base</p></div><div class="hero-caption">'''+image('hero','Original studio still life of a blank walnut name block, ivory notebook and brass pen','hero-photo')+'''<div class="photo-label">Walnut desk block + everyday notebook<br>Browse each base and its own text limits.</div></div></section><section class="process" aria-label="How it works"><article><span class="number">01</span><div><h3>Choose a base</h3><p>Material, shape and available variant.</p></div></article><article><span class="number">02</span><div><h3>Make it personal</h3><p>Enter text within the product’s limits.</p></div></article><article><span class="number">03</span><div><h3>Check every detail</h3><p>Review the exact text before adding.</p></div></article></section><div class="row between"><p class="small">Start with the object. Finish with your meaning.</p>'''+a('Explore the two bases '+icon('ArrowRight'),'03-collection')+'''</div></main>'''+study(),'/', 'Home opening; 01 + 02 compose one homepage')
# 02 HOME BOTTOM
save('02-home-bottom','Two bases. Many meanings.','Base merchandising, examples and limitations, production care and footer.',header()+'''<main><section class="wrap section"><div class="sectionhead"><div><span class="eyebrow">Begin with a good base</span><h1>Two bases. Many meanings.</h1><p>Choose the object first. Its material and method set the rules for your words.</p></div>'''+a('All bases '+icon('ArrowRight'),'03-collection')+'''</div><div class="product-grid">'''+card('block')+card('notebook')+'''</div></section><section class="wrap section education-grid"><div><span class="eyebrow">A few words go a long way</span><h2>A name, made intentional.</h2><p style="margin-top:20px">For this walnut base: letters A–Z, spaces, apostrophes and hyphens. One line, up to 18 characters. Keep the spelling and case you want made.</p><div class="example-words"><span>Asha</span><span>O'Neil</span><span>Amal-Rae</span></div><p class="small" style="margin-top:20px">Examples of permitted text. Different bases can have different limits. No artwork uploads or proof approvals.</p></div><div class="panel"><h3>What happens after review?</h3>'''+facts([('1 · Accepted text','Validated before cart'),('2 · Distinct item','One configuration per line'),('3 · Order record','Accepted wording retained'),('4 · Making','Merchant receives that wording')])+'''</div></section><section class="wrap section"><div class="service-grid"><article>'''+icon('Info')+'''<h3>Know the constraints</h3><p>Check text length, characters and placement on your chosen base.</p></article><article>'''+icon('Package')+'''<h3>Know what is being made</h3><p>Read the exact written summary. Preview images are illustrative.</p></article><article>'''+icon('CircleHelp')+'''<h3>Need to change something?</h3><p>Edit and revalidate before checkout. After ordering, contact the merchant before production.</p></article></div></section></main>'''+study()+footer(),'/','Homepage continuation of scene 01')
# 03 COLLECTION
save('03-collection','Choose your base','Meaningful base cards, search, method and price facets, sort and honest single-page pagination.',header()+crumb('All bases')+'''<main class="wrap section" style="padding-top:8px"><div class="collection-intro"><div><span class="eyebrow">01 / Choose</span><h1>Choose your base.</h1><p style="margin-top:16px">Every object starts blank.<br>See the method and text limit before you choose.</p></div><div class="searchbox">'''+icon('Search')+'''<input aria-label="Search base products" placeholder="Search a base or material"><button class="iconbtn" aria-label="Search">'''+icon('ArrowRight')+'''</button></div></div><div class="catalog"><aside class="facets"><h3>Filter bases</h3><div class="facet-group"><strong class="small">Product</strong><label><input type="checkbox">Desk objects</label><label><input type="checkbox">Notebooks</label></div><div class="facet-group"><strong class="small">Personalization</strong><label><input type="checkbox">Engraving</label><label><input type="checkbox">Cover print</label></div><div class="facet-group"><strong class="small">Price</strong><label><input type="checkbox">Under ₹1,000</label><label><input type="checkbox">₹1,000–₹1,500</label></div><p class="small">Text only. No upload or logo-printing filter.</p></aside><div><div class="sortbar"><span class="count">2 bases · All methods</span><div class="row"><button class="button secondary mobile-filter">'''+icon('SlidersHorizontal')+''' Filters (0)</button><label>Sort by <select aria-label="Sort bases"><option>Featured</option><option>Price: low to high</option></select></label></div></div><div class="product-grid">'''+card('block')+card('notebook')+'''</div><nav class="pagination" aria-label="Pagination"><button class="iconbtn" disabled aria-label="Previous page">'''+icon('ArrowLeft')+'''</button><span>Page 1 of 1 · 2 products</span><button class="iconbtn" disabled aria-label="Next page">'''+icon('ArrowRight')+'''</button></nav></div></div></main>'''+study()+footer(),'/collections/bases','Unfiltered two-product collection; controls proposed pending real query contract')
# 04 PDP CHOOSE
save('04-product-main','First, choose your base.','Gallery, INR price, real named fixture variant and unavailable alternative; configuration-first purchase entry.',header()+crumb('Desk name block')+'''<main class="wrap section" style="padding-top:0">'''+steps(1)+'''<div class="workspace"><div>'''+stage()+'''<div class="thumbs">'''+image('block','Front angle of walnut block')+image('hero','Walnut block in desk setting')+'''</div></div><section class="purchase"><span class="eyebrow">01 / The object</span><h1>Desk name block</h1><div class="row between"><span class="price">₹1,290</span><span class="badge">Text included</span></div><p>A quiet place for your name. Solid walnut, with one line of engraving on the front face.</p><fieldset class="field"><legend>Material — Walnut</legend><div class="options"><label class="option"><input type="radio" name="wood" checked>Walnut</label><label class="option unavailable"><input type="radio" name="wood" disabled>Oak · Unavailable</label></div></fieldset><div class="availability">Available in Walnut</div>'''+facts([('Dimensions','20 × 5 × 3 cm'),('Personalization','Front engraving'),('Text limit','18 characters · 1 line'),('Price for this selection','₹1,290, including text')])+'''<div class="row" style="margin:24px 0"><span class="small">Quantity</span><div class="qty"><button aria-label="Decrease quantity">'''+icon('Minus')+'''</button><span>1</span><button aria-label="Increase quantity">'''+icon('Plus')+'''</button></div></div>'''+btn('Continue to your text '+icon('ArrowRight'),'05-product-specify')+'''<p class="small" style="margin-top:18px">You’ll review the exact configuration before adding to cart.</p></section></div></main>'''+study()+footer(),'/products/desk-name-block','Choose state of same PDP as 05/06')
# 05 PDP SPECIFY
save('05-product-specify','Make space for your words.','Bounded text workspace with retained invalid input, precise error, last-valid illustrative preview and correction path.',header()+context('Your text')+'''<main class="wrap section">'''+steps(2)+'''<div class="sectionhead"><div><span class="eyebrow">02 / The words</span><h1>Make space for your words.</h1></div></div><div class="workspace"><div>'''+stage(True,True)+'''<p class="aside-note">Your spelling and letter case are preserved. Engraving texture and exact visual placement can vary.</p></div><section><div class="panel"><h2 style="font-size:24px">Your engraving text</h2><p class="small" style="margin-top:12px">1–18 characters. Letters A–Z, spaces, apostrophes and hyphens. No emoji or other symbols.</p>'''+field('Text to engrave','Asha ✦','6 / 18 characters · One line', 'Remove “✦”. This base accepts letters A–Z, spaces, apostrophes and hyphens.',id='engraving-text')+'''<div style="margin-top:20px">'''+notice('Your edit is retained. The preview still shows the last valid text “Asha”. Nothing has been added to cart.','error')+'''</div><fieldset class="field"><legend>Letter style</legend><div class="options"><label class="option"><input type="radio" name="style" checked>Sans</label><label class="option"><input type="radio" name="style">Serif</label></div></fieldset>'''+facts([('Placement','Centered on front face'),('Base + text','₹1,290'),('Text surcharge','₹0')])+'''<div class="stack" style="margin-top:24px"><button class="button wide" disabled>Review configuration</button>'''+btn('Remove symbol & review “Asha” '+icon('ArrowRight'),'06-product-review',True)+'''</div><p class="small" style="margin-top:16px">A text change is checked again before price and availability are confirmed.</p></div></section></div><section class="section"><span class="eyebrow">Know the boundaries</span><div class="service-grid"><article><h3>Length is product-defined</h3><p>This base allows one line with at most 18 characters, including spaces and punctuation.</p></article><article><h3>No silent corrections</h3><p>We never change the case, spelling or characters without showing you the accepted result.</p></article><article><h3>Other scripts</h3><p>This fixture’s engraving method supports A–Z only. A merchant must explicitly enable and validate another script.</p></article></div></section></main>'''+study()+footer(),'/products/desk-name-block','Specify state with invalid symbol; no new PDP route')
# 06 REVIEW
save('06-product-review','Check it. Make it yours.','Exact authoritative review, deliberate acceptance, policy details and independent notebook link.',header()+context('Review')+'''<main class="wrap section">'''+steps(3)+'''<div class="sectionhead"><div><span class="eyebrow">03 / Your final check</span><h1>Check it. Make it yours.</h1><p>Read the words below exactly as you want them made.</p></div><span class="badge good">'''+icon('CheckCircle2')+''' Configuration validated</span></div><div class="workspace"><div>'''+stage(True)+'''</div><section class="config-card"><div class="row between"><h2 style="font-size:24px">Your accepted configuration</h2>'''+a('Edit','05-product-specify')+'''</div><span class="eyebrow" style="margin:24px 0 8px">Exact text · Case preserved</span><div class="exact-text">Asha</div>'''+facts([('Base / material','Desk name block / Walnut'),('Text method','Front engraving'),('Letter style / placement','Sans / Centered'),('Text length','4 of 18 characters'),('Quantity','1'),('Text surcharge','₹0'),('Item total','₹1,290')])+'''<label class="checkrow" style="margin:24px 0"><input type="checkbox" checked>I checked the spelling, letter case and placement in this written summary.</label>'''+btn('Add this configuration '+icon('ShoppingBag'),'07-cart')+'''<p class="small" style="margin-top:16px">The written summary is authoritative. The photo preview is illustrative.</p></section></div><section class="section education-grid"><div><span class="eyebrow">Before we make it</span><h2>Made to your wording.</h2><ul class="labelled-list" style="margin-top:24px"><li>'''+icon('Check')+'''Edit and revalidate text before checkout.</li><li>'''+icon('Info')+'''After ordering, ask the merchant about changes before production starts.</li><li>'''+icon('Package')+'''Dispatch estimate is unavailable in this sample. Checkout confirms available shipping options.</li><li>'''+icon('CircleHelp')+'''For an incorrect or damaged item, contact the merchant with your order reference.</li></ul></div><article class="panel"><span class="eyebrow">Another base to explore</span><div class="row start">'''+image('notebook','Ivory linen notebook','')+'''</div><h3 style="margin-top:20px">Everyday notebook</h3><p class="small" style="margin:12px 0 20px">₹790 · Up to 12 characters<br>Independently purchased and configured.</p>'''+a('View notebook details '+icon('ArrowRight'),'notebook-reference')+'''</article></section></main>'''+study()+footer(),'/products/desk-name-block','Validated review/continuation state of same PDP')
# 07 CART
save('07-cart','Your words, kept separate.','Two configurations of the same walnut SKU, per-line editing/quantity/removal, preserved edit on failure, correct subtotal.',header()+'''<main class="wrap section"><div class="sectionhead"><div><span class="eyebrow">Your cart / 2 configured items</span><h1>Your words, kept separate.</h1><p>Same base. Different text. Each configuration stays its own item.</p></div>'''+a('Keep choosing','03-collection')+'''</div><div class="cart-grid"><section>'''+cartline('Asha','01')+cartline('Kabir','02')+'''<details class="panel" open><summary><strong>Edit text for configuration 02</strong></summary>'''+field('Updated text','Kabir-Rae','9 / 18 characters',id='cart-edit')+'''<div style="margin:20px 0">'''+notice('We couldn’t revalidate “Kabir-Rae”. Your accepted item still says “Kabir”; your new text is retained. Retry the same edit.','error')+'''</div><div class="row">'''+btn('Revalidate same edit','07-cart')+a('Cancel edit','07-cart')+'''</div><p class="small" style="margin-top:16px">Checkout waits until this edit is resolved or cancelled.</p></details></section>'''+summary(False,'<div style="margin-top:24px"><button class="button wide" disabled>Resolve edit to check out</button><p class="small" style="margin:14px 0">Cancel or finish the edit, then continue.</p>'+btn('Cancel edit & continue','08-checkout-address',True)+'</div>')+'''</div></main>'''+study()+footer(),'/cart','Separate configurations; network-failed edit retained; cancellation returns to accepted cart')
# 08 CHECKOUT ADDRESS
save('08-checkout-address','Where should it go?','Canonical address step, contact/phone validation, shipping quote and exact configured summary.',checkout_header()+'''<main class="checkout-wrap section">'''+checkoutsteps(1)+'''<div class="checkout-grid"><section><span class="eyebrow">Address & delivery</span><h1>Where should it go?</h1><p class="small">Checking out as asha@example.test · '''+a('Change account','10-sign-in')+'''</p><div class="panel" style="margin-top:24px"><h2>Delivery address</h2><div class="formgrid">'''+field('Full name','Asha Mehta')+field('Mobile number','','','Enter the recipient’s 10-digit mobile number.','tel','10-digit mobile')+'''<div class="full">'''+field('Address','24 Example Lane')+'''</div>'''+field('Area / locality','Sample Nagar')+field('Pincode','560001')+field('City','Bengaluru')+field('State','Karnataka')+'''</div><p class="small" style="margin-top:20px">Country / India</p><label class="checkrow" style="margin-top:20px"><input type="checkbox">Save this address to my LetBuyy account</label></div><section class="panel" style="margin-top:24px"><h2>Shipping</h2><label class="shipping-choice"><span class="row between"><span><input type="radio" checked name="shipping"> Standard shipping</span><strong>₹80</strong></span><p class="small">Illustrative server quote · Delivery estimate unavailable</p></label></section><div class="stack" style="margin-top:24px"><button class="button wide" disabled>Add mobile number to continue</button>'''+a('View next resolved state '+icon('ArrowRight'),'09-checkout-review')+'''</div></section>'''+summary()+'''</div>'''+checkoutfoot()+'''</main>''','checkout.letbuyy.com/address','Incomplete recipient phone; resolved next scene shown separately')
# 09 CHECKOUT REVIEW
save('09-checkout-review','One last look.','Full configured summary, address and eligible mock method; uncertain result recovery checks original attempt.',checkout_header()+'''<main class="checkout-wrap section">'''+checkoutsteps(2)+'''<div class="checkout-grid review"><section><span class="eyebrow">Review & payment</span><h1>One last look.</h1><p>Two names. Two items. Check the exact wording before payment.</p><section class="panel" style="margin-top:24px"><div class="row between"><h2>Deliver to</h2>'''+a('Edit','08-checkout-address')+'''</div>'''+address()+'''<hr class="divider"><p class="small">asha@example.test<br>Recipient phone provided<br>Standard shipping · ₹80<br>Delivery estimate unavailable</p></section><section class="panel" style="margin-top:24px"><div class="row between"><h2>Payment</h2><span class="badge outline">Mock provider</span></div><label class="pay-choice"><input type="radio" name="payment" checked><span><strong>Online payment</strong><p>UPI or card through the configured payment provider. This study processes no payment.</p></span></label><p class="small" style="margin-top:16px">Cash on delivery is unavailable for this illustrative quote. Actual eligibility comes from checkout.</p></section><div style="margin-top:24px">'''+notice('The previous attempt’s result could not be confirmed. Check that attempt before starting another payment. Your configuration is retained.','error')+'''</div><div style="margin-top:24px">'''+btn('Check original payment attempt '+icon('RefreshCw'),'09-checkout-review')+'''</div><p class="small" style="margin-top:16px">After reconciliation, the commitment action is “Pay ₹2,660”. It stays unavailable while the earlier result is unknown.</p><button class="button wide" disabled style="margin-top:20px">Pay ₹2,660 · Checking prior attempt</button><p class="small" style="margin-top:16px">We’ll check the same payment attempt. Your names and item choices stay unchanged.</p></section>'''+summary()+'''</div>'''+checkoutfoot()+'''</main>''','checkout.letbuyy.com/review','Unknown prior payment result; reconcile original intent before commitment')
