save('12-profile','Hello, Asha.','Store-scoped profile overview, supported name edit and useful account navigation.',account('''<span class="eyebrow">Your MadeYours account</span><h1>Hello, Asha.</h1><p class="lead">Your details, addresses and orders, all in one place.</p><div class="account-cards"><section class="panel"><div class="row between"><h2>Your profile</h2><span class="badge">Editing</span></div>'''+field('Full name','Asha Mehta')+'''<div class="field"><span class="small">Sign-in email</span><p id="profile-email" style="color:var(--ink)">asha@example.test</p></div>'''+'''<div class="row" style="margin-top:24px">'''+btn('Save profile','12-profile')+a('Cancel','12-profile')+'''</div></section><section class="panel"><h2>Your latest order</h2><span class="badge good">Accepted · Mock fulfillment</span><h3 style="margin-top:24px">MY-1042</h3><p class="small" style="margin-top:12px">22 Oct 2026 · 2 configured items<br>Text: Asha / Kabir<br>Total ₹2,660</p><div style="margin-top:24px">'''+btn('View your order '+icon('ArrowRight'),'14-order-detail',True)+'''</div></section><section class="panel"><h2>Saved address</h2>'''+address()+'''<div style="margin-top:20px">'''+a('Manage addresses','15-addresses')+'''</div></section><section class="panel"><h2>Your LetBuyy identity</h2><p class="small">You use one buyer account across LetBuyy. This storefront only shows your MadeYours orders.</p><div style="margin-top:24px">'''+a('Sign-in & account help','identity-recovery')+'''</div></section></div>''','12-profile'),'/account','Editing full name; sign-in email is read-only text')
# 13 ORDERS
save('13-orders','Your MadeYours orders.','Store-scoped order history, configured-item context, status and direct owned order entry.',account('''<span class="eyebrow">Order history</span><h1>Your MadeYours orders.</h1><p class="lead">Find the exact configuration behind every order.</p><div class="row between" style="margin-bottom:24px"><span class="small">1 order · MadeYours only</span><label class="small">Period <select style="padding:10px;border-radius:6px;border:1px solid var(--line);background:white"><option>All dates</option></select></label></div><div style="border:1px solid var(--soft);border-radius:8px;overflow:hidden"><table class="order-history"><thead><tr><th>Order</th><th>Date</th><th>Items</th><th>Status</th><th>Total</th><th></th></tr></thead><tbody><tr><td data-label="Order"><strong>MY-1042</strong><p>Mock provider / fulfillment</p></td><td data-label="Date">22 Oct 2026</td><td data-label="Items">2 desk blocks<p>Text: Asha / Kabir</p></td><td data-label="Status"><span class="badge good">Accepted</span></td><td data-label="Total"><strong>₹2,660</strong></td><td>'''+a('View order '+icon('ArrowRight'),'14-order-detail')+'''</td></tr></tbody></table></div><nav class="pagination" aria-label="Orders pagination"><span>Page 1 of 1 · 1 order</span></nav><div class="panel" style="margin-top:32px"><h2>Need the exact wording?</h2><p class="small">Open the order to see each item’s accepted text, style and placement.</p><div style="margin-top:20px">'''+a('Continue choosing bases','03-collection')+'''</div></div>''','13-orders'),'/account/orders','One fictional owned order; no other merchant orders exposed')
