save('15-addresses','Your saved places.','Default address and edit form with recoverable pincode validation, uncommitted changes and default choice.',account('''<span class="eyebrow">Saved addresses</span><h1>Your saved places.</h1><p class="lead">Your LetBuyy address book. Only the address you choose is shared for an order.</p><div class="addresses-grid"><section class="panel"><div class="row between"><h2>Home</h2><span class="badge good">Default</span></div>'''+address()+'''<div class="row" style="margin-top:24px">'''+a('Edit','15-addresses')+a('Remove','15-addresses')+'''</div><hr class="divider">'''+btn('Add another address','address-add',True)+'''</section><section class="panel"><div class="row between"><h2>Edit Home</h2><span class="badge">Unsaved</span></div><p class="small">Your saved address stays unchanged until this form is accepted.</p><div class="formgrid">'''+field('Full name','Asha Mehta')+field('Address label','Home')+'''<div class="full">'''+field('Address','24 Example Lane')+'''</div>'''+field('Area / locality','Sample Nagar')+field('Pincode','5600','', 'Enter a 6-digit Indian pincode.',id='address-pincode')+field('City','Bengaluru')+field('State','Karnataka')+'''</div><label class="checkrow" style="margin:24px 0"><input type="checkbox" checked>Use as my default address</label>'''+notice('Check the pincode. Your other entries are retained.','error')+'''<div class="row" style="margin-top:24px"><button class="button" disabled>Save changes</button>'''+a('Cancel edit','15-addresses')+'''</div></section></div>''','15-addresses'),'/account/addresses','Default list + editing validation; add state is supplementary source, not another required route')
