def supplement(id,title,content):
 (S/f'{id}.html').write_text(f'<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{title}</title><link rel="stylesheet" href="styles.css"><script defer src="presentation.js"></script></head><body>{content}</body></html>')
