supplement('identity-continue','Continue to MadeYours',identity('''<h1>Continue to MadeYours</h1><p>You’re signed in to LetBuyy as <strong>asha@example.test</strong>. MadeYours will receive your email address.</p><div class="stack" style="margin-top:28px">'''+btn('Continue to MadeYours','12-profile')+btn('Use a different account','10-sign-in',True)+'''</div><p class="small">This visual state represents explicit continuation. It does not submit an authorization request.</p>'''))
supplement('identity-recovery','Reset your password',identity('''<h1>Reset your password</h1><p>Enter your email and LetBuyy will send a 6-digit recovery code if the account is eligible.</p>'''+field('Email','asha@example.test',type='email')+'''<div class="stack" style="margin-top:24px"><button class="button" type="button">Send code · Visual reference</button>'''+a('Return to sign in','10-sign-in')+'''</div><p class="small">No email is sent by this study. The actual recovery flow uses the emailed code and a new password, then returns to the canonical sign-in/Continue destination.</p>'''))
supplement('support-reference','Order help reference',header()+'''<main class="wrap section stack"><span class="eyebrow">Order support / MY-1042</span><h1>Keep the order in context.</h1><p>Contact the merchant using its configured support channel. Include MY-1042 and the item’s accepted text. This visual study does not send a message or promise cancellation.</p>'''+btn('Return to order','14-order-detail')+'''</main>'''+footer())
supplement('address-add','Add an address',account('''<span class="eyebrow">Supplementary add state</span><h1>Add an address.</h1><section class="panel"><div class="formgrid">'''+field('Full name',placeholder='Recipient name')+field('Address label',placeholder='For example, Home')+field('Address',placeholder='Building and street')+field('Pincode',placeholder='6-digit pincode')+field('City')+field('State')+'''</div><label class="checkrow" style="margin:24px 0"><input type="checkbox">Use as default address</label><div class="row"><button class="button" disabled>Save address</button>'''+a('Cancel','15-addresses')+'''</div></section>''','15-addresses'))
(R/'scenes.json').write_text(json.dumps(scenes,indent=2,ensure_ascii=False)+'\n')
(R/'prototype-index.html').write_text('<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>MadeYours responsive sources</title><link rel="stylesheet" href="source/styles.css"></head><body><main class="wrap section"><span class="eyebrow">Visual-only source / design v1</span><h1>MadeYours responsive story.</h1><p style="margin-top:24px">15 connected scenes. Home and PDP continuation states share their intended production route. No API, identity, order or payment mutation is implemented.</p><nav class="stack" style="margin-top:32px">'+''.join(f'<a class="panel" href="{s["source"]}"><strong>{s["id"]} · {s["title"]}</strong><p class="small">{s["description"]}</p></a>' for s in scenes)+'</nav><div class="review-nav"><a class="button" href="index.html">Image gallery</a><a class="button secondary" href="comparisons/index.html">Research comparison</a></div></main></body></html>')
